begin;
create extension if not exists pgtap with schema extensions;
set local search_path=logos_academy,extensions;
select plan(25);
insert into uploaded_files(id,tenant_id,student_profile_id,activity_assignment_id,uploaded_by_user_id,storage_path,filename_encrypted,content_type,size_bytes,status)
values (md5('mvp068-file-1')::uuid,'10000000-0000-0000-0000-000000000001','13000000-0000-0000-0000-000000000001','1a000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000002',('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text),extensions.pgp_sym_encrypt('snapshot.txt','test-key'),'text/plain',10,'pending'),
(md5('mvp068-file-2')::uuid,'10000000-0000-0000-0000-000000000001','13000000-0000-0000-0000-000000000001','1a000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000002',('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-2')::uuid::text),extensions.pgp_sym_encrypt('other.txt','test-key'),'text/plain',10,'pending');
insert into storage.objects(bucket_id,name,metadata) values
('submissions',('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text),'{"size":10,"mimetype":"text/plain","fixtureDigest":"original"}'),
('submissions',(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/11111111-1111-1111-1111-111111111111'),'{"size":10,"mimetype":"text/plain","fixtureDigest":"inspected"}'),
('submissions',(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/33333333-3333-3333-3333-333333333333'),'{"size":11,"mimetype":"text/plain"}');
set local role authenticated;
select set_config('request.jwt.claim.sub','a0000000-0000-0000-0000-000000000002',true);
select throws_ok($$insert into storage.objects(bucket_id,name,metadata) values('submissions',(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/22222222-2222-2222-2222-222222222222'),'{"size":10,"mimetype":"text/plain"}')$$,'42501',null,'client cannot create a verified object before its row points there');
select results_eq($$update storage.objects set metadata='{"size":10,"mimetype":"text/plain","fixtureDigest":"attacker"}' where bucket_id='submissions' and name=(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/11111111-1111-1111-1111-111111111111') returning name$$,$$select name from storage.objects where false$$,'client cannot alter an unreferenced verified object');
select throws_ok($$update storage.objects set name=(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/22222222-2222-2222-2222-222222222222') where bucket_id='submissions' and name=('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)$$,'42501',null,'client cannot rename pending object into verified destination');
select lives_ok($$update storage.objects set metadata='{"size":10,"mimetype":"text/plain","fixtureDigest":"changed-after-inspection"}' where bucket_id='submissions' and name=('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)$$,'client can change original pending object without changing snapshot');
select throws_ok($$select logos_academy.student_finalize_verified_upload('10000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000002',md5('mvp068-file-1')::uuid,(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/11111111-1111-1111-1111-111111111111'),'test-key')$$,'42501',null,'authenticated cannot finalize snapshot directly');
reset role;
set local role service_role;
select throws_ok($$select logos_academy.student_finalize_verified_upload('10000000-0000-0000-0000-000000000001','21000000-0000-0000-0000-000000000002',md5('mvp068-file-1')::uuid,(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/11111111-1111-1111-1111-111111111111'),'test-key')$$,'42501','file not available','foreign actor cannot finalize file');
select throws_ok($$select logos_academy.student_finalize_verified_upload('20000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000002',md5('mvp068-file-1')::uuid,(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/11111111-1111-1111-1111-111111111111'),'test-key')$$,'42501','file not available','foreign tenant cannot finalize file');
select throws_ok($$select logos_academy.student_finalize_verified_upload('10000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000002',md5('mvp068-file-1')::uuid,('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text),'test-key')$$,'22023','invalid verified storage path','original mutable path is not a verified snapshot');
select throws_ok($$select logos_academy.student_finalize_verified_upload('10000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000002',md5('mvp068-file-2')::uuid,(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/11111111-1111-1111-1111-111111111111'),'test-key')$$,'22023','invalid verified storage path','same metadata does not authorize another file prefix');
select throws_ok($$select logos_academy.student_finalize_verified_upload('10000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000002',md5('mvp068-file-1')::uuid,(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/11111111-1111-1111-1111-111111111111')||'/extra','test-key')$$,'22023','invalid verified storage path','verified path rejects additional segments');
select throws_ok($$select logos_academy.student_finalize_verified_upload('10000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000002',md5('mvp068-file-1')::uuid,(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/44444444-4444-4444-4444-444444444444'),'test-key')$$,'23514','verified uploaded object mismatch','missing immutable object is rejected');
select throws_ok($$select logos_academy.student_finalize_verified_upload('10000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000002',md5('mvp068-file-1')::uuid,(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/33333333-3333-3333-3333-333333333333'),'test-key')$$,'23514','verified uploaded object mismatch','snapshot size mismatch is rejected');
select is((logos_academy.student_finalize_verified_upload('10000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000002',md5('mvp068-file-1')::uuid,(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/11111111-1111-1111-1111-111111111111'),'test-key')->>'status'),'ready','backend finalizes inspected snapshot');
select is((logos_academy.student_finalize_verified_upload('10000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000002',md5('mvp068-file-1')::uuid,(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/11111111-1111-1111-1111-111111111111'),'test-key')->>'filename'),'snapshot.txt','same destination retry returns normal UploadedFile projection');
select throws_ok($$select logos_academy.student_finalize_verified_upload('10000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000002',md5('mvp068-file-1')::uuid,(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/22222222-2222-2222-2222-222222222222'),'test-key')$$,'23505','file already finalized to another path','ready file cannot switch verified destination');
reset role;
select is((select storage_path from uploaded_files where id=md5('mvp068-file-1')::uuid),(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/11111111-1111-1111-1111-111111111111'),'ready row points exclusively to inspected immutable copy');
select is((select metadata->>'fixtureDigest' from storage.objects where bucket_id='submissions' and name=(select storage_path from uploaded_files where id=md5('mvp068-file-1')::uuid)),'inspected','changing pending original did not change finalized snapshot');
select is((select metadata->>'fixtureDigest' from storage.objects where bucket_id='submissions' and name=('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)),'changed-after-inspection','race fixture actually changed original before finalize');
set local role authenticated;
select throws_ok($$update storage.objects set metadata='{"size":10,"mimetype":"text/plain","fixtureDigest":"attacker"}' where bucket_id='submissions' and name=(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/11111111-1111-1111-1111-111111111111')$$,'42501',null,'client cannot overwrite ready snapshot');
select results_eq($$update storage.objects set metadata='{"size":10,"mimetype":"text/plain"}' where bucket_id='submissions' and name=('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text) returning name$$,$$select name from storage.objects where false$$,'client loses original path authorization after finalize');
select is((select count(*)::integer from storage.objects where bucket_id='submissions' and name=(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/11111111-1111-1111-1111-111111111111')),1,'owner can read ready snapshot');
reset role;
select throws_ok($$update uploaded_files set storage_path=(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/22222222-2222-2222-2222-222222222222') where id=md5('mvp068-file-1')::uuid$$,'42501','verified file path transition required','trigger rejects path replacement even by raw backend update');
select ok(not has_function_privilege('authenticated','logos_academy.student_finalize_upload(uuid,uuid,uuid,text)','execute'),'legacy finalize stays revoked from authenticated');
select ok(not has_function_privilege('authenticated','logos_academy.finalize_uploaded_file(uuid,uuid)','execute'),'earlier finalize stays revoked from authenticated');
set local role anon;
select throws_ok($$select logos_academy.student_finalize_verified_upload('10000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000002',md5('mvp068-file-1')::uuid,(('10000000-0000-0000-0000-000000000001'::text||'/'||'13000000-0000-0000-0000-000000000001'::text||'/'||'1a000000-0000-0000-0000-000000000001'::text||'/'||md5('mvp068-file-1')::uuid::text)||'/verified/11111111-1111-1111-1111-111111111111'),'test-key')$$,'42501',null,'anon cannot call verified finalize');
reset role;
select * from finish();
rollback;
